// ───────────────────────────── Test zone ─────────────────────────────
// A virtual chat that lives inside the extension. Everything reaches it through
// chatApi, so the interceptor, reply processing, guard, fights, party, people and
// phone all run exactly as they would in a real chat — without touching one.
// Demo mode plays scripted turns (no tokens); Live mode asks the model, with a small
// world narrator standing in for a bot card.

const RPGC_VERSION = '2.9.0-beta';
const diagLog = [];
function diagPush(kind, m) { diagLog.push({ at: new Date().toISOString(), kind, text: String(m).slice(0, 400) }); if (diagLog.length > 60) diagLog.shift(); }
function logW(m) { diagPush('warn', m); return spindle.log.warn(m); }
function logE(m) { diagPush('error', m); return spindle.log.error(m); }

const SANDBOX_ID = '__rpgc_test_zone__';
const SANDBOX_FILE = 'test-zone.json';
let sandbox = null;          // { world, mode, messages, seq, turn, busy, fight }
let rpgcInterceptor = null;  // the registered interceptor, callable by the test zone
let rpgcGenEnded = null;     // the registered reply handler, likewise
let encounterChatNow = null; // which chat the running fight step belongs to
let lastRealChatId = null;   // the last real chat the panel showed; the test zone borrows its persona

const chatApi = {
    async getMessages(id) { return id === SANDBOX_ID ? (sandbox ? sandbox.messages : []) : spindle.chat.getMessages(id); },
    async updateMessage(id, mid, patch) {
        if (id !== SANDBOX_ID) return spindle.chat.updateMessage(id, mid, patch);
        const m = sandbox && sandbox.messages.find(x => x.id === mid);
        if (!m) return null;
        if (patch && patch.content !== undefined) m.content = patch.content;
        if (patch && isPlainObject(patch.metadata)) m.metadata = { ...(m.metadata || {}), ...patch.metadata };
        if (patch && isPlainObject(patch.reasoning) && patch.reasoning.text !== undefined) m.extra = { ...(m.extra || {}), reasoning: patch.reasoning.text };
        await saveSandbox();
        return m;
    },
    async appendMessage(id, msg, opts) {
        if (id !== SANDBOX_ID) return spindle.chat.appendMessage(id, msg, opts);
        if (!sandbox) return null;
        const m = { id: 'tz' + (++sandbox.seq), role: msg.role, content: msg.content, swipe_id: 0, metadata: isPlainObject(msg.metadata) ? msg.metadata : {} };
        sandbox.messages.push(m);
        await saveSandbox();
        if (opts && opts.triggerGeneration) setTimeout(() => sandboxGenerate().catch(e => logW(`[RPG Companion HMS] Test zone turn failed: ${e?.message || e}`)), 0);
        return { id: m.id };
    },
    async setMessagesHidden(id, ...rest) { return id === SANDBOX_ID ? null : spindle.chat.setMessagesHidden(id, ...rest); }
};

function registerInterceptorKeep(fn, ...rest) { rpgcInterceptor = fn; return spindle.registerInterceptor(fn, ...rest); }
function onGenerationEnded(fn) { rpgcGenEnded = fn; return spindle.on('GENERATION_ENDED', fn); }

async function saveSandbox() {
    if (!sandbox) return;
    try { await spindle.storage.setJson(SANDBOX_FILE, { ...sandbox, busy: false, messages: sandbox.messages.slice(-120) }); } catch { /* best effort */ }
}
async function loadSandbox() {
    try { const s = await spindle.storage.getJson(SANDBOX_FILE, { fallback: null }); if (isPlainObject(s) && Array.isArray(s.messages)) sandbox = { ...s, busy: false }; } catch { /* none yet */ }
}

