function sandboxNext() {
    const w = SANDBOX_WORLDS[sandbox.world] || SANDBOX_WORLDS.rezero;
    const n = w.script.length;
    const i = sandbox.turn++;
    // After the script, it loops with the calendar moving on, so the clock never runs backward.
    const day = (sandbox.world === 'cote' ? 14 : 1) + Math.floor(i / n) * 3 + (i % n >= 2 ? 1 : 0);
    return w.script[i % n](day);
}

/** Runs a reply through the same code a real chat reply goes through, always in together mode. */
async function sandboxGenerate() {
    if (!sandbox || sandbox.busy) return;
    const sb = sandbox;
    sb.busy = true;
    setStatus(SANDBOX_ID, 'busy', sandbox.mode === 'live' ? 'The model is writing…' : 'Playing the next demo turn…');
    await pushState(SANDBOX_ID);
    const saved = settings.generationMode;
    try {
        settings.generationMode = 'together';
        let content;
        if (sandbox.mode === 'live') {
            const userName = await getUserName(SANDBOX_ID);
            const w = SANDBOX_WORLDS[sandbox.world] || SANDBOX_WORLDS.rezero;
            const msgs = [{ role: 'system', content: w.narrator.replace(/USER/g, userName) }, ...sandbox.messages.map(m => ({ role: m.role, content: textOf(m.content), __isChatHistory: true }))];
            const out = rpgcInterceptor ? await rpgcInterceptor(msgs, { chatId: SANDBOX_ID, generationType: 'normal' }) : null;
            let cid = null;
            try { cid = await sideConnectionId(null); } catch { /* leave it to Lumiverse */ }
            const res = await withTimeout(spindle.generate.quiet({ messages: (out && out.messages) || msgs, ...(cid ? { connection_id: cid } : {}), ...userOpt() }), Math.max(20, Number(settings.trackerTimeoutSec) || 180) * 1000);
            content = String(res?.content || '').trim() || '(The model returned nothing.)';
        } else {
            const cst = await getChatState(SANDBOX_ID);
            content = immActive(cst) ? sandboxImmReply(cst.immersive, await getUserName(SANDBOX_ID)) : sandboxNext();
        }
        if (sandbox !== sb) return;                  // started over while this turn was being written
        const m = { id: 'tz' + (++sandbox.seq), role: 'assistant', content, swipe_id: 0, metadata: {} };
        sandbox.messages.push(m);
        await saveSandbox();
        if (rpgcGenEnded) await rpgcGenEnded({ chatId: SANDBOX_ID, messageId: m.id, generationType: 'normal' }, activeUserId);
    } catch (e) {
        setStatus(SANDBOX_ID, 'error', `Test zone: ${e?.message || e}`);
    } finally {
        settings.generationMode = saved;
        sb.busy = false;
        await pushState(SANDBOX_ID);
    }
}

async function sandboxStart(p) {
    const world = SANDBOX_WORLDS[p.world] ? p.world : 'rezero';
    sandbox = { world, mode: p.mode === 'live' ? 'live' : 'demo', messages: [], seq: 0, turn: 0, busy: false, fight: 0 };
    hmsCache.delete(SANDBOX_ID);
    chatStateCache.delete(SANDBOX_ID);
    userNameCache.delete(SANDBOX_ID);
    const st = emptyChatState();
    st.party = { members: SANDBOX_WORLDS[world].party.map(n => ({ name: n, key: lockKey(n), aliases: [] })) };
    await saveChatState(SANDBOX_ID, st);
    sandbox.messages.push({ id: 'tz' + (++sandbox.seq), role: 'user', content: 'Begin.', swipe_id: 0, metadata: {} });
    await saveSandbox();
    await sandboxGenerate();
}

/** Scripted game-master answers for fights in Demo mode, shaped like the real ones. */
function sandboxFightReply(messages) {
    const t = messages.map(m => m.content).join('\n');
    if (/Combat has ended with result/.test(t)) {
        const lastHud = [...(sandbox.messages || [])].reverse().map(m => parseHud(textOf(m.content))).find(Boolean);
        const hud = lastHud ? lastHud.lines.map(l => l.text).join('\n') : '';
        return (hud ? `### WORLD STATE ###\n${hud}\n***\n` : '') + 'When it is over, the silence rings. You are breathing hard, but you are alive.';
    }
    if (/FORMAT \(D&D 5e-style stat blocks\)/.test(t)) {
        return JSON.stringify({ party: [{ name: 'You', hp: 22, maxHp: 22, ac: 14, init: 2, saves: { str: 2, dex: 2, con: 1, int: 0, wis: 1, cha: 1 }, attacks: [{ name: 'Shortsword', toHit: 5, damage: '1d6+3' }], spells: [{ name: 'Healing Word', level: 1, heal: '1d4+2' }], slots: { '1': [2, 2] }, isPlayer: true }],
            enemies: [{ name: 'Mabeast', hp: 18, maxHp: 18, ac: 12, init: 1, saves: { dex: 1 }, attacks: [{ name: 'Bite', toHit: 4, damage: '1d8+2' }], threat: 'even', description: 'A horned wolf with red eyes', sprite: '🐺', intent: 'Go for the throat', telegraph: 'It circles, low to the ground', plan: { action: 'attack', use: 'Bite', target: 'You' } }], environment: 'A moonlit clearing' });
    }
    if (/ALREADY ROLLED AND RESOLVED/.test(t)) return JSON.stringify({ narrative: 'Steel and teeth in the moonlight.', plans: [{ name: 'Mabeast', action: 'attack', use: 'Bite', target: 'You' }], enemyIntents: [{ enemyName: 'Mabeast', intent: 'Keep biting', telegraph: 'It snarls and lowers its head' }] });
    // Only a round asks for "combatStats"; a setup never does.
    if (!/"combatStats"/.test(t)) {
        sandbox.fight = 0;
        return JSON.stringify({ party: [{ name: 'You', hp: 80, maxHp: 100, physical: [{ name: 'Strike', type: 'single-target' }], magical: [], abilities: [{ name: 'Dirty Trick', type: 'single-target' }], items: ['Bandage x2'], isPlayer: true }],
            enemies: [{ name: 'Mabeast', hp: 60, maxHp: 60, threat: 'even', physical: [{ name: 'Bite', type: 'single-target' }], description: 'A horned wolf with red eyes', sprite: '🐺', intent: 'Go for the throat', telegraph: 'It circles, low to the ground' }], environment: 'A moonlit clearing' });
    }
    sandbox.fight = (sandbox.fight || 0) + 1;
    const hp = Math.max(0, 60 - sandbox.fight * 25);
    return JSON.stringify({ combatStats: { party: [{ name: 'You', hp: 80 - sandbox.fight * 8, maxHp: 100 }], enemies: [{ name: 'Mabeast', hp, maxHp: 60 }] }, playerOutcome: 'success',
        enemyActions: [{ enemyName: 'Mabeast', action: 'lunges and grazes your leg', target: 'You', outcome: 'partial' }],
        enemyIntents: [{ enemyName: 'Mabeast', intent: 'Flee if hurt again', telegraph: 'Its ears flatten' }],
        intel: /This is a CHECK/.test(t) ? [{ target: 'Mabeast', facts: [{ kind: 'weakness', text: 'Its left foreleg is lame' }, { kind: 'intent', text: 'It will flee if hurt again' }] }] : [],
        narrative: hp ? 'You drive it back a step.' : 'The beast falls still.', ...(hp ? {} : { combatEnd: true, result: 'victory' }) });
}

// ───────────────────────────── Interceptor (prompt injection) ─────────────────────────────

function textOf(content) {
    if (typeof content === 'string') return content;
    if (Array.isArray(content)) return content.filter(p => p && p.type === 'text').map(p => p.text).join('\n');
    return '';
}

function appendText(message, extra) {
    if (typeof message.content === 'string') {
        message.content = message.content + '\n\n' + extra;
    } else if (Array.isArray(message.content)) {
        message.content = [...message.content, { type: 'text', text: extra }];
    } else {
        message.content = extra;
    }
}

// ───────────────────────────── Preset handshake ─────────────────────────────
// A preset can carry the extension's request for the reply in a slot of its own, where it fits the
// preset's reply shape, instead of the extra system message added just before the player's turn:
//     {{if::{{matches::{{rpgc_on}}::^1$}}}}{{rpgc_request}}{{/if}}
// The guard matters: Lumiverse leaves an unknown macro as literal text, so without the extension
// {{rpgc_on}} stays "{{rpgc_on}}" and the slot stays empty. When the slot delivered the request, the
// interceptor sees its head line and does not add it again; any other preset gets today's message.
// {{rpgc_fight}} is "1" while a fight runs, for a preset's fight-craft block.

const RPGC_SLOT_HEAD = '[RPG Companion \u2014 for this reply]';

/** What an HMS reply is asked for besides the story: the side-panel block, a dice result, the optional extras. */
async function hmsRequestParts(chatId, chat, gt, excludeId, userName, slot, committed = null) {
    chat = trackingBefore(chat, excludeId);
    const parts = [];
    if (oocTurnIn(chat, excludeId)) return parts;          // an OOC question: the guide answers, no side-panel block
    reqChatNow = chatId;
    const cst = await getChatState(chatId);
    if (settings.generationMode === 'together' && gt !== 'continue' && companionWanted(cst, chat)) {
        const data = committed || (await collectCommitted(chatId, chat, excludeId)).data;
        parts.push(buildCompanionInstruction(data, userName, cst.locks, immStView(cst, excludeId), chat, slot ? 'slot' : false, { excludeId }));
    }
    if (gt !== 'continue') {
        const dl = diceLine(userName, false, chatId).trim();
        if (dl) parts.push(dl);
    }
    parts.push(...extraFeaturePrompts(true, userName));
    return parts;
}

/** The {{rpgc_request}} macro: the same request, worded for a preset slot. Never writes anything. */
async function rpgcSlotRequest(mctx) {
    if (!settings.enabled) return '';
    const chatId = mctx && mctx.chatId;
    if (!chatId || chatId === SANDBOX_ID) return '';
    const env = (mctx && mctx.env) || {};
    const gt = (env.system && env.system.lastGenerationType) || 'normal';
    if (gt === 'impersonate' || gt === 'quiet') return '';
    let chat = await chatApi.getMessages(chatId);
    const card = env.character ? `${env.character.personality || ''}\n${env.character.description || ''}` : '';
    if (!isHmsChat(chatId, card ? [{ content: card }] : null, chat)) return '';      // classic chats keep their own tracker prompt
    injNoteCore(chatId, card);                       // a bot that keeps its own wounds: no injuries asked
    const last = chat[chat.length - 1];
    const excludeId = (gt === 'swipe' || gt === 'regenerate') && last && last.role === 'assistant' ? last.id : null;
    chat = trackingBefore(chat, excludeId);
    const userName = (env.names && String(env.names.user || '').trim()) || await getUserName(chatId);
    const parts = await hmsRequestParts(chatId, chat, gt, excludeId, userName, true);
    if (!parts.length) return '';
    return `${RPGC_SLOT_HEAD}\n${parts.join('\n\n')}`;
}

/** The {{rpgc_minds}} macro: the Minds state for a preset block, or empty. Never writes anything. */
async function rpgcMindsMacro(mctx) {
    if (!settings.enabled || !simWanted() || !simCfg().tell) return '';
    const chatId = mctx && mctx.chatId;
    if (!chatId || chatId === SANDBOX_ID) return '';
    const env = (mctx && mctx.env) || {};
    const gt = (env.system && env.system.lastGenerationType) || 'normal';
    if (gt === 'impersonate' || gt === 'quiet' || gt === 'continue') return '';
    let chat = await chatApi.getMessages(chatId);
    if (!isHmsChat(chatId, null, chat)) return '';
    const last = chat[chat.length - 1];
    const excludeId = (gt === 'swipe' || gt === 'regenerate') && last && last.role === 'assistant' ? last.id : null;
    chat = trackingBefore(chat, excludeId);
    if (oocTurnIn(chat, excludeId)) return '';
    const userName = (env.names && String(env.names.user || '').trim()) || await getUserName(chatId);
    return simStateText(simFold(chat, await getChatState(chatId), { excludeId, userName }), chat, userName);
}

function registerHandshakeMacros() {
    if (typeof spindle.registerMacro !== 'function') return;     // an older Lumiverse: the interceptor does it all
    const def = (name, description, handler) => {
        try { spindle.registerMacro({ name, category: 'RPG Companion', description, returnType: 'string', volatile: true, handler }); }
        catch (e) { logW(`[RPG Companion HMS] Could not register {{${name}}}: ${e?.message || e}`); }
    };
    def('rpgc_on', 'RPG Companion: "1" while the extension is running and switched on, else empty. Guard {{rpgc_request}} with it.',
        () => (settings.enabled ? '1' : ''));
    def('rpgc_request', 'RPG Companion: what this reply is asked for besides the story (the side-panel block, a dice result, the optional extras), worded for a preset slot after the chat. Empty when nothing is needed. When a preset carries it, the extension does not add its own message.',
        // Lumiverse gives a macro 5 s and then prints a timeout notice into the prompt; give up first and leave it to the interceptor.
        async (mctx) => { try { return await withTimeout(rpgcSlotRequest(mctx), 4000); } catch (e) { logW(`[RPG Companion HMS] {{rpgc_request}} ${e?.message === 'TIMEOUT' ? 'took too long' : 'failed'}, the extension will add its own message${e?.message === 'TIMEOUT' ? '' : ': ' + (e?.message || e)}`); return ''; } });
    def('rpgc_marks', 'RPG Companion: "1" while replies are asked to mark dialogue as [D:Speaker:mood]"…"[/D] (the extension draws colours, emoji and names from them), else empty.',
        () => (dialogueMarksOn() ? '1' : ''));
    def('rpgc_emoji', 'RPG Companion: "1" while the extension draws emoji reading cues before dialogue, else empty. A preset\'s own emoji instruction should stand down then.',
        () => (settings.enabled && chatDisplayCfg().emoji ? '1' : ''));
    def('rpgc_chronicle', 'RPG Companion: the Chronicle\'s key moments so far (settled replies only), one line each, or empty. For a preset that wants the story\'s turning points without the Memory Cortex.',
        async (mctx) => { try { const id = mctx && mctx.chatId; return id ? await withTimeout(chronicleMacro(id), 3500) : ''; } catch { return ''; } });
    def('rpgc_minds', 'RPG Companion: the Minds state (from FrankenSIM): how the people in the story feel, what they are doing, what they know and the details still waiting to pay off, kept by the extension. Empty when it is off or nothing is known yet. When a preset carries it, the extension does not add its own message.',
        async (mctx) => { try { return await withTimeout(rpgcMindsMacro(mctx), 3500); } catch { return ''; } });
    def('rpgc_fight', 'RPG Companion: "1" while a fight is running in this chat, else empty.',
        async (mctx) => { try { const id = mctx && mctx.chatId; if (!settings.enabled || !id) return ''; return immActive(await getChatState(id)) ? '1' : ''; } catch { return ''; } });
}
registerHandshakeMacros();

const injectedPromptPasses = new WeakSet();
registerInterceptorKeep(async (messages, context) => {
    if (injectedPromptPasses.has(messages)) return messages;
    if (context && context.chatId && context.generationType !== 'quiet') generating.set(context.chatId, Date.now());
    // The connection the player's own reply runs on is what "Same as my chat" follows for the extension's calls.
    if (context && context.chatId && context.connectionId && context.generationType !== 'quiet' && context.chatId !== SANDBOX_ID) {
        noteUser(context.userId);
        noteChatConnection(context.chatId, context.connectionId, context.userId || activeUserId);
    }
    try {
        if (!settings.enabled) return messages;
        const ctx = context || {};
        noteUser(ctx.userId);
        sheetChatNow = ctx.chatId || null;
        const gt = ctx.generationType || 'normal';
        if (gt === 'impersonate' || gt === 'quiet') return messages;
        const chatId = ctx.chatId;
        if (!chatId) return messages;

        let chat = await chatApi.getMessages(chatId);
        const last = chat[chat.length - 1];
        const excludeId = (gt === 'swipe' || gt === 'regenerate') && last && last.role === 'assistant' ? last.id : null;
        chat = trackingBefore(chat, excludeId);
        // an OOC question is answered by the bot's guide: no HUD, no story, so nothing of ours goes in
        if (oocTurnIn(chat, excludeId)) return messages;
        const { data: committed } = await collectCommitted(chatId, chat, excludeId);
        const userName = await getUserName(chatId);
        const locks = (await getChatState(chatId)).locks;

        const out = messages.map(m => ({ ...m }));
        const injected = []; // { msg, name }

        // Positions relative to chat history (depth semantics like ST extension prompts)
        let lastHistoryIdx = -1;
        let lastAssistantHistoryIdx = -1;
        out.forEach((m, i) => {
            if (m.__isChatHistory) {
                lastHistoryIdx = i;
                if (m.role === 'assistant') lastAssistantHistoryIdx = i;
            }
        });
        if (lastHistoryIdx === -1) lastHistoryIdx = out.length - 1;

        const trailing = []; // depth 0 content
        let exampleMsg = null;
        let contextMsg = null;

        const hmsOn = isHmsChat(chatId, messages, chat);
        for (const m of messages) injNoteCore(chatId, textOf(m.content));     // a bot that keeps its own wounds
        let contextName = 'RPG Companion: scene context';
        const trailingName = hmsOn ? 'side-panel request' : 'tracker instructions';
        // A preset with the {{rpgc_request}} slot (HMS Reporter) already carries this reply's request:
        // then it is not added a second time.
        const slotted = hmsOn && out.some(m => !m.__isChatHistory && textOf(m.content).includes(RPGC_SLOT_HEAD));
        if (hmsOn) {
            // HMS: the HUD is the tracker. Only ask for the companion block, and never touch the HUD.
            if (!slotted) trailing.push(...await hmsRequestParts(chatId, chat, gt, excludeId, userName, false, committed));
            const ctxParts = [], ctxNames = [];
            if (settings.hmsPinReminder) {
                const rem = pinsReminder(await getChatState(chatId));
                if (rem) { ctxParts.push(rem); ctxNames.push('pinned HUD lines'); }
            }
            const sv = hmsCfg().survival;
            if (sv.enabled && sv.tellModel && gt !== 'continue') {
                try {
                    const tl = hmsTimeline(chat);
                    const cur = tl.length ? hmsReadSystems(tl[tl.length - 1].hud) : null;
                    const rem = hmsSurvivalReminder(hmsSurvival(tl, await getChatState(chatId), hmsCfg(), cur), userName);
                    if (rem) { ctxParts.push(rem); ctxNames.push('survival clock'); }
                } catch (e) { logW(`[RPG Companion HMS] Survival clock failed: ${e?.message || e}`); }
            }
            {
                const lastU = [...chat].reverse().find(m => m.role === 'user');
                if (lastU && lastU === chat[chat.length - 1] && textOf(lastU.content).trim() === WORLD_MOVES_MARK) {
                    ctxParts.push((settings.customWorldMovesPrompt || '').trim() || DEFAULT_WORLD_MOVES_PROMPT);
                    ctxNames.push('world moves');
                }
            }
            if (commsCfg().on && gt !== 'continue') {
                const lastUser = [...chat].reverse().find(m => m.role === 'user');
                const note = lastUser ? commsNote(textOf(lastUser.content), userName) : null;
                if (note && lastUser === chat[chat.length - 1]) { ctxParts.push(note); ctxNames.push('phone'); }
            }
            if (youCfg().on && youCfg().tell && gt !== 'continue') {
                try { const tl = hmsTimeline(chat); const r = youReminder(hmsYouPanel(chat, await getChatState(chatId), null, tl.length ? hmsReadSystems(tl[tl.length - 1].hud) : null), userName); if (r) { ctxParts.push(r); ctxNames.push('level-up'); } } catch { /* optional */ }
            }
            if (magicCfg().on && gt !== 'continue') {
                try { const r = spellStudyReminder(chatId, chat, await getChatState(chatId), userName); if (r) { ctxParts.push(r); ctxNames.push('spell study'); } } catch { /* optional */ }
            }
            if (ctxParts.length) { contextMsg = { role: 'system', content: ctxParts.join('\n\n') }; contextName = `RPG Companion: ${ctxNames.join(' + ')} (~${Math.round(ctxParts.join('').length / 4)} tokens)`; }
        } else if (settings.generationMode === 'together') {
            if (gt !== 'continue') {
                const instructions = generateTrackerInstructions(userName, true, true, locks) + classicExtrasRequest(immStView(await getChatState(chatId), excludeId), chat, userName);
                if (instructions) trailing.push(instructions.trim());
                const example = buildTrackerExample(applyLocksForPrompt(committed, locks));
                if (example && lastAssistantHistoryIdx > 0) {
                    exampleMsg = { role: 'assistant', content: '```json\n' + example + '\n```' };
                }
            }
        } else {
            const summary = generateContextualSummary(committed, userName);
            if (summary) {
                const instr = settings.customContextInstructionsPrompt || DEFAULT_CONTEXT_INSTRUCTIONS_PROMPT;
                contextMsg = { role: 'system', content: `<context>\n${summary}\n${instr}\n</context>` };
            }
        }
        if (!hmsOn) trailing.push(...extraFeaturePrompts(false, userName));      // HMS: part of hmsRequestParts

        if (gt !== 'continue' && chapCfg().inPrompt) {
            const chB = chaptersBlock(await getChatState(chatId), userName, null, chat);
            if (chB) {
                if (contextMsg) { contextMsg.content = `${chB}\n\n${contextMsg.content}`; contextName = `RPG Companion: the story so far + ${String(contextName || '').replace(/^RPG Companion:\s*/, '')}`; }
                else { contextMsg = { role: 'system', content: chB }; contextName = `RPG Companion: the story so far (~${Math.round(chB.length / 4)} tokens)`; }
            }
        }

        if (gt !== 'continue' && injCfg().on && injCfg().tell && injActive(chat)) {
            const ist = await getChatState(chatId);
            const lastHud = latestHudMessage(chat);
            const iB = injBlock(ist, userName, lastHud ? chapterMark(lastHud).minutes : null, chat);
            if (iB) {
                if (contextMsg) { contextMsg.content = `${contextMsg.content}\n${iB}`; contextName = `${contextName} + injuries`; }
                else { contextMsg = { role: 'system', content: iB }; contextName = `RPG Companion: injuries (~${Math.round(iB.length / 4)} tokens)`; }
            }
        }

        // Minds (FrankenSIM): the state of the people in the story, as memory, before the player's turn.
        // A preset that carries {{rpgc_minds}} (HMS Reporter) already has it in its own block.
        if (hmsOn && gt !== 'continue' && simWanted() && simCfg().tell && !out.some(m => !m.__isChatHistory && textOf(m.content).includes(SIM_STATE_HEAD))) {
            try {
                const sTxt = simStateText(simFold(chat, await getChatState(chatId), { excludeId, userName }), chat, userName);
                if (sTxt) {
                    if (contextMsg) { contextMsg.content = `${contextMsg.content}\n\n${sTxt}`; contextName = `${contextName} + minds`; }
                    else { contextMsg = { role: 'system', content: sTxt }; contextName = `RPG Companion: minds (~${Math.round(sTxt.length / 4)} tokens)`; }
                }
            } catch (e) { logW(`[RPG Companion HMS] Minds state failed: ${e?.message || e}`); }
        }

        // The immersive fight rides upstream here, in every mode — HMS and classic alike. This is
        // the whole mechanism: the live pools, plus what each body looks like at that level in
        // words, so the engine writes the wound instead of forgetting it between replies. It goes
        // ahead of any other context because a fighter's condition governs everything else in the
        // reply. A continue is mid-sentence, so it is left alone.
        if (gt !== 'continue') {
            const immSt = await getChatState(chatId);
            if (immActive(immSt)) {
                const view = immViewFor(immSt.immersive, excludeId);
                // The exchange this reply answers: the last message, or the one before a reply being redone.
                const anchor = chat[chat.length - 1];
                const lr = settings.lastDiceRoll;
                const manual = lr && (!lr.chatId || lr.chatId === chatId) && !(settings.dnd && settings.dnd.enabled === false) ? lr : null;
                const dice = immDiceFor(immSt.immersive, anchor ? anchor.id : null, !!(view.pending && view.pending.exploit), immRules(), { skipPlayer: !!manual });
                if (dice && dice.fresh) await saveChatState(chatId, immSt);
                const rem = immReminder(view, userName, { dice, manual });
                if (rem) {
                    if (contextMsg) {
                        contextMsg.content = `${rem}\n\n${contextMsg.content}`;
                        contextName = `RPG Companion: the fight + ${String(contextName || '').replace(/^RPG Companion:\s*/, '')}`;
                    } else {
                        contextMsg = { role: 'system', content: rem };
                        contextName = 'RPG Companion: the fight';
                    }
                }
            }
        }

        // depth 0: right after the last history message
        if (trailing.length) {
            let block = trailing.join('\n\n');
            const anchor = out[lastHistoryIdx];
            const approx = Math.round(block.length / 4);
            // Default: its own system message just before the player's turn, so the turn stays the last
            // thing the model reads and the block reads as an extra rather than the task.
            if (settings.injectPlacement !== 'append' && anchor && anchor.role === 'user' && anchor.__isChatHistory) {
                block = `[RPG Companion — for after your reply] Write your full reply first, at its usual length and in its usual form, following all your own instructions. This is an extra, never a replacement for any of it:\n\n${block}`;
                const msg = { role: 'system', content: block };
                out.splice(lastHistoryIdx, 0, msg);
                lastHistoryIdx++;
                injected.push({ msg, name: `RPG Companion: ${trailingName} (~${approx} tokens, before your message)` });
            } else if (anchor && anchor.role === 'user' && anchor.__isChatHistory) {
                appendText(anchor, block);
                injected.push({ msg: anchor, name: `RPG Companion: ${trailingName} (~${approx} tokens, added to your message)` });
            } else {
                const msg = { role: 'user', content: block };
                out.splice(lastHistoryIdx + 1, 0, msg);
                injected.push({ msg, name: `RPG Companion: ${trailingName}` });
            }
        }
        // depth 1: before the last history message
        if (contextMsg) {
            out.splice(Math.max(0, lastHistoryIdx), 0, contextMsg);
            injected.push({ msg: contextMsg, name: contextName });
            if (lastAssistantHistoryIdx >= lastHistoryIdx) lastAssistantHistoryIdx++;
        }
        // previous tracker state: just before the last assistant reply in history
        if (exampleMsg) {
            out.splice(lastAssistantHistoryIdx, 0, exampleMsg);
            injected.push({ msg: exampleMsg, name: 'RPG Companion: previous trackers' });
        }

        if (slotted) {
            const sl = out.find(m => !m.__isChatHistory && textOf(m.content).includes(RPGC_SLOT_HEAD));
            const tok = sl ? Math.round(textOf(sl.content).slice(textOf(sl.content).indexOf(RPGC_SLOT_HEAD)).length / 4) : 0;
            spindle.log.info(`[RPG Companion HMS] Side-panel request: in the preset's slot (~${tok} tokens), not added again.`);
            if (!injected.length) { lastInjection.set(chatId, { at: new Date().toISOString(), parts: [`side-panel request (~${tok} tokens, in the preset)`] }); return messages; }
        }
        if (!injected.length) return messages;
        spindle.log.info(`[RPG Companion HMS] Injected (${hmsOn ? 'HMS, ' : ''}${settings.generationMode}, ${gt}): ${injected.map(i => i.name.replace('RPG Companion: ', '')).join(', ')}`);

        const breakdown = injected
            .map(({ msg, name }) => ({ messageIndex: out.indexOf(msg), name }))
            .filter(b => b.messageIndex >= 0);
        if (context && context.chatId) lastInjection.set(context.chatId, { at: new Date().toISOString(), parts: (breakdown || []).map(b => b.name).concat(slotted ? ['side-panel request (in the preset)'] : []) });
        injectedPromptPasses.add(out);
        return { messages: out, breakdown };
    } catch (e) {
        logE(`[RPG Companion HMS] Interceptor error: ${e?.message || e}`);
        return messages;
    }
}, 60);

// ───────────────────────────── In-chat display: HUD card and dialogue ─────────────────────────────
// Both are drawn when a message is shown, never written into it: the saved reply keeps its plain-text
// HUD (every carrier line keeps loading its lorebook entry) and its dialogue markers, so switching
// either off, or changing the colours, needs no regeneration and works on old messages too.

function chatDisplayCfg() {
    const c = isPlainObject(settings.chatDisplay) ? settings.chatDisplay : {};
    return {
        hudCard: c.hudCard !== false,
        hudTheme: c.hudTheme === 'app' ? 'app' : 'world',
        hudRawOpen: c.hudRawOpen === true,
        colours: c.colours === true,
        emoji: c.emoji === true,
        names: c.names === true,
        tones: c.tones !== false,      // FrankenSIM's tone of voice: whisper, steady, tremble, bite (typography only)
        palette: typeof c.palette === 'string' ? c.palette : '',
        // under each reply: the Internal States panel, the thoughts alone, or nothing
        states: ['panel', 'thoughts', 'off'].includes(c.states) ? c.states : (settings.showThoughtsInChat === false ? 'off' : 'panel'),
        statesTab: ['scene', 'people', 'minds', 'bonds', 'plot', 'map'].includes(c.statesTab) ? c.statesTab : 'people',
        statesOpen: c.statesOpen !== false
    };
}
/** Whether replies should carry [D:…] markers at all. */
function dialogueMarksOn(cfg = chatDisplayCfg()) { return !!(settings.enabled && (cfg.colours || cfg.emoji || cfg.names)); }

// ── HUD card ──

// The four wiki looks the panel themes use, as the card's own colours. 'app' follows Lumiverse.
const HUD_CARD_THEMES = {
    app: { bg: 'color-mix(in srgb, var(--lumiverse-fill-subtle, rgba(127,127,127,.08)) 100%, transparent)', fg: 'var(--lumiverse-text, inherit)', mute: 'var(--lumiverse-text-muted, #999)',
        band: 'color-mix(in srgb, var(--lumiverse-primary, #8c82ff) 22%, transparent)', bandFg: 'var(--lumiverse-text, inherit)', acc: 'var(--lumiverse-primary, #8c82ff)',
        line: 'var(--lumiverse-border, rgba(127,127,127,.35))', soft: 'color-mix(in srgb, var(--lumiverse-primary, #8c82ff) 10%, transparent)', font: 'inherit' },
    rezero: { bg: '#100d18', fg: '#ecebf5', mute: '#b3aed0', band: 'linear-gradient(90deg, #7b5bb8, #5a3f96)', bandFg: '#fff', acc: '#2ad4cf', line: '#3a2f5c', soft: 'rgba(123, 91, 184, .16)', font: 'inherit' },
    overlord: { bg: '#141313', fg: '#eaeaea', mute: '#b8b8b8', band: 'linear-gradient(#4a4a4a, #2f2f2f)', bandFg: '#fff', acc: '#d65151', line: '#4a4a4a', soft: 'rgba(214, 81, 81, .12)', font: "Georgia, 'Times New Roman', serif" },
    cote: { bg: '#ffffff', fg: '#1d2433', mute: '#4f5b70', band: 'linear-gradient(#f0578e, #d92a62)', bandFg: '#fff', acc: '#d61f5c', line: '#f0bdd0', soft: '#fff0f5', font: "'Segoe UI', system-ui, sans-serif" },
    mushoku: { bg: '#fdf7ea', fg: '#3b2a1e', mute: '#6d5642', band: '#c0392b', bandFg: '#fff', acc: '#a2551f', line: '#e2cfae', soft: '#f6ead2', font: 'inherit' }
};

// Lumiverse runs markdown over text inside a card's block elements, which turns each into a paragraph.
// So every element that holds text is a <span> (laid out by the CSS), and the <div>s hold only elements.
const HUD_CARD_CSS = `
.rh{--rh-bg:#15151b;--rh-fg:#ddd;--rh-mute:#999;--rh-band:#333;--rh-band-fg:#fff;--rh-acc:#8c82ff;--rh-line:#444;--rh-soft:rgba(127,127,127,.12);
  display:block;margin:0 0 1em;border:1px solid var(--rh-line);border-radius:10px;background:var(--rh-bg);color:var(--rh-fg);overflow:hidden;line-height:1.5;font-size:.95em}
.rh *{box-sizing:border-box}
.rh p{margin:0;display:contents}
.rh-band{display:flex;flex-wrap:wrap;align-items:baseline;gap:.15em .6em;padding:.5em .85em;background:var(--rh-band);color:var(--rh-band-fg)}
.rh-band .t{font-weight:700}
.rh-band .d{opacity:.5}
.rh-band .tag{margin-left:auto;font-size:.68em;letter-spacing:.12em;text-transform:uppercase;opacity:.85;white-space:nowrap}
.rh-path{display:flex;flex-wrap:wrap;align-items:center;gap:.1em .3em;padding:.45em .85em;border-bottom:1px solid var(--rh-line);font-size:.92em}
.rh-path .s{color:var(--rh-mute)} .rh-path .s.here{color:var(--rh-fg);font-weight:700}
.rh-path .gt{color:var(--rh-acc);opacity:.8}
.rh-grid{display:grid;grid-template-columns:minmax(6.5em,max-content) 1fr;gap:.3em .9em;padding:.6em .85em}
.rh-row{display:contents}
.rh-k{display:block;color:var(--rh-mute);font-size:.78em;font-weight:600;letter-spacing:.05em;text-transform:uppercase;padding-top:.22em;overflow-wrap:anywhere}
.rh-v{display:block;min-width:0;overflow-wrap:anywhere}
.rh-wide{grid-column:1 / -1}
.rh-c>.rh-k::after,.rh-mod.rh-c>.mt::after{content:" \\2022";color:var(--rh-acc)}
.rh-chips{display:flex;flex-wrap:wrap;gap:.3em}
.rh-chip{display:inline-block;padding:.05em .55em;border:1px solid var(--rh-line);border-radius:999px;background:var(--rh-soft);font-size:.9em}
.rh-bar{display:inline-block;vertical-align:middle;width:7em;height:.5em;margin-right:.55em;border-radius:999px;background:var(--rh-soft);border:1px solid var(--rh-line);overflow:hidden}
.rh-bar>.f{display:block;height:100%;background:var(--rh-acc)}
.rh-bar.low>.f{background:#e0a030} .rh-bar.crit>.f{background:#e05050}
.rh-q{display:flex;flex-wrap:wrap;align-items:baseline;gap:.15em .5em;padding:.1em 0}
.rh-q+.rh-q{border-top:1px dashed var(--rh-line)}
.rh-q .n{font-weight:600}
.rh-code{font-family:var(--lumiverse-font-mono, ui-monospace, monospace);font-size:.78em;color:var(--rh-mute)}
.rh-st{font-size:.8em;padding:0 .5em;border-radius:999px;border:1px solid var(--rh-line)}
.rh-st.on{border-color:var(--rh-acc);color:var(--rh-acc)} .rh-st.done{opacity:.7} .rh-st.bad{border-color:#e05050;color:#e05050}
.rh-mods{display:flex;flex-direction:column;gap:.35em;padding:0 .85em .65em}
.rh-mod{display:block;padding:.35em .6em;border-left:3px solid var(--rh-acc);border-radius:6px;background:var(--rh-soft);font-size:.92em}
.rh-mod>.mt{font-size:.78em;font-weight:700;letter-spacing:.06em;text-transform:uppercase;margin-right:.45em;color:var(--rh-acc)}
.rh-blk{display:block;margin:0 .85em .65em;padding:.45em .65em;border:1px dashed var(--rh-line);border-radius:8px}
.rh-blk>.h{display:block;margin:0 0 .3em;font-size:.75em;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--rh-acc)}
.rh-blk>.r{display:block;font-size:.92em}
.rh-blk .rh-k{display:inline;padding:0;margin-right:.4em}
.rh-legend{display:block;padding:0 .85em .5em;font-size:.72em;color:var(--rh-mute)}
.rh-legend>.dot{color:var(--rh-acc)}
details.rh-raw{display:block;border-top:1px solid var(--rh-line)}
details.rh-raw>summary{cursor:pointer;list-style:none;padding:.35em .85em;font-size:.75em;color:var(--rh-mute)}
details.rh-raw>summary::-webkit-details-marker{display:none}
details.rh-raw>summary::before{content:"\\25B8  "} details.rh-raw[open]>summary::before{content:"\\25BE  "}
details.rh-raw pre{margin:0;padding:.5em .85em .7em;white-space:pre-wrap;font-family:var(--lumiverse-font-mono, ui-monospace, monospace);font-size:.8em;color:var(--rh-fg);background:transparent;border:0}
`.replace(/\n\s*/g, '');

/** Card theme variables for a world, as an inline style. */
function hudCardVars(world, cfg) {
    const t = cfg.hudTheme === 'app' ? HUD_CARD_THEMES.app : (HUD_CARD_THEMES[world] || HUD_CARD_THEMES.app);
    return `--rh-bg:${t.bg};--rh-fg:${t.fg};--rh-mute:${t.mute};--rh-band:${t.band};--rh-band-fg:${t.bandFg};--rh-acc:${t.acc};--rh-line:${t.line};--rh-soft:${t.soft};font-family:${t.font}`;
}

const HUD_VALUE_BAR_RE = /^(\d[\d,.]*)\s*\/\s*(\d[\d,.]*)(\s.*)?$/;
const HUD_LIST_LABEL_RE = /equip|item|inventor|gear|belonging|skill|abilit|spell|trait|title|talent|blessing|condition|status|effect|part(y|ies)|member|compan|contact|language|tag|perk|feat/i;

/** One value: a bar for "84/100", chips for a list, else the text. */
function hudCardValue(label, value) {
    const v = String(value || '').trim();
    if (!v) return '';
    const bm = v.match(HUD_VALUE_BAR_RE);
    if (bm && !/^(year|month|day|week|arc|floor|seat|standings?|chapter|part|volume|loop)\b/i.test(label || '')) {
        const a = Number(bm[1].replace(/,/g, '')), b = Number(bm[2].replace(/,/g, ''));
        if (b > 0 && a >= 0 && a <= b * 1.5) {
            const pct = Math.max(0, Math.min(100, Math.round(a / b * 100)));
            return `<span class="rh-bar${pct <= 15 ? ' crit' : pct <= 40 ? ' low' : ''}" aria-hidden="true"><span class="f" style="width:${pct}%"></span></span>${escapeHtml(v)}`;
        }
    }
    const dot = v.split(/\s+·\s+/);
    if (dot.length >= 3) return `<span class="rh-chips">${dot.map(x => `<span class="rh-chip">${escapeHtml(x)}</span>`).join('')}</span>`;
    // a list of short items under a list-like label ("Equipment: Student phone, School uniform")
    if (HUD_LIST_LABEL_RE.test(label || '') && /,\s/.test(v) && !/\d,\d/.test(v)) {
        const parts = v.split(/,\s+/);
        if (parts.length >= 2 && parts.length <= 14 && parts.every(p => p.length <= 48 && !/[.;!?]$/.test(p))) {
            return `<span class="rh-chips">${parts.map(x => `<span class="rh-chip">${escapeHtml(x)}</span>`).join('')}</span>`;
        }
    }
    return escapeHtml(v);
}

function hudQuestState(s) {
    const t = String(s || '').toLowerCase();
    if (/fail|lost|expired|abandon/.test(t)) return 'bad';
    if (/complete|done|resolved|cleared|success/.test(t)) return 'done';
    return t ? 'on' : '';
}

/** "08:10 (Before Homeroom)" was read as label "08": a label ending in a digit before a value starting with two is a time. */
function hudFieldsFixed(fields) {
    return (fields || []).map(f => (f.label && /\d$/.test(f.label) && /^\d{2}\b/.test(f.value)) ? { label: null, value: `${f.label}:${f.value}` } : f);
}

/** The card itself, from a parsed HUD. Returns an HTML island (its own <style>), or null. */
function hudCardHtml(hud, rawHud, cfg = chatDisplayCfg()) {
    if (!hud || !Array.isArray(hud.lines) || !hud.lines.length) return null;
    const hc = hmsCfg();
    const world = worldOf(worldLines(hud));
    const lines = hud.lines.filter(l => l.block !== 'fence');
    const free = lines.filter(l => !l.block);
    const locIdx = free.findIndex(l => l.kind === 'location');
    let top = locIdx > 0 ? free.slice(0, Math.min(locIdx, 2)) : [];
    if (!top.length && free[0] && free[0].kind === 'field' && /\b\d{1,2}:\d{2}\b/.test(free[0].text)) top = [free[0]];
    const qLabels = new Set(hmsList(hc.quests && hc.quests.labels ? hc.quests.labels : 'Quests, Quest, Objectives, Objective, Missions, Mission').map(x => x.toLowerCase()));
    const carrier = (l) => { try { return hmsIsCarrier(l.key, hc); } catch { return false; } };
    const label = (s) => escapeHtml(String(s || '').replace(/^[^\p{L}\p{N}\[]+/u, '').trim());
    const row = (c, k, v) => `<div class="rh-row${c}"><span class="rh-k">${k}</span><span class="rh-v">${v}</span></div>`;

    let html = `<div class="rh not-island-prose" style="${hudCardVars(world, cfg)}" role="group" aria-label="World state">`;
    // band: the date and time, written as the HUD writes them
    const bandBits = [];
    for (const l of top) for (const part of l.text.trim().split(/\s+\|\s+/)) {
        if (bandBits.length) bandBits.push('<span class="d">|</span>');
        bandBits.push(`<span class="${bandBits.length ? '' : 't'}">${escapeHtml(part)}</span>`);
    }
    html += `<div class="rh-band">${bandBits.join('')}<span class="tag">${escapeHtml(world ? WORLD_LABEL[world] || 'World state' : 'World state')}</span></div>`;
    // the location path
    const loc = free.find(l => l.kind === 'location');
    if (loc && loc.segments && loc.segments.length) {
        const segs = loc.segments.map((s, i) => `<span class="s${i === loc.segments.length - 1 ? ' here' : ''}">${escapeHtml(s)}</span>`);
        html += `<div class="rh-path" title="Location (keeps its lorebook entries loading)"><span aria-hidden="true">📍</span>${segs.join('<span class="gt" aria-hidden="true">›</span>')}</div>`;
    }
    // the fields
    const rows = [], mods = [];
    for (const l of free) {
        if (top.includes(l) || l === loc) continue;
        const c = carrier(l) ? ' rh-c' : '';
        if (l.kind === 'module') {
            mods.push(`<span class="rh-mod${c}">${l.value ? `<span class="mt">${escapeHtml(l.tag)}</span>${escapeHtml(l.value)}` : `<span class="mt">${escapeHtml(l.tag)}</span>`}</span>`);
            continue;
        }
        const fields = hudFieldsFixed(l.fields);
        const f0 = fields[0];
        if (f0 && f0.label && qLabels.has(f0.label.toLowerCase())) {
            const body = l.text.slice(l.text.indexOf(':') + 1).trim();
            const qs = body.split(/\s*;\s*|\s+\|\s+|\s+·\s+/).map(q => q.trim()).filter(Boolean).map(q => {
                const m = q.match(/^(.*\S)\s+[—–-]\s+(.+)$/);
                const name = m ? m[1].trim() : q, state = m ? m[2].trim() : '';
                const bc = name.match(/\s*(#\d{4,})\b/);
                const bare = bc ? name.replace(bc[0], '').trim() : name;
                return `<span class="rh-q"><span class="n">${escapeHtml(bare)}</span>${bc ? `<span class="rh-code">${escapeHtml(bc[1])}</span>` : ''}${state ? `<span class="rh-st ${hudQuestState(state)}">${escapeHtml(state)}</span>` : ''}</span>`;
            });
            rows.push(row(c, label(f0.label), qs.join('')));
            continue;
        }
        if (!f0 || !f0.label) {
            // "Standings 4/1 — DRAGON 1000 (A) · CROWN 1000 (B)": a label before a dash, then the value
            const m = l.text.trim().match(/^(.{2,40}?)\s+[—–]\s+(.+)$/);
            if (m) { rows.push(row(c, label(m[1]), hudCardValue(m[1], m[2]))); continue; }
            rows.push(`<div class="rh-row${c}"><span class="rh-v rh-wide">${hudCardValue('', l.text.trim())}</span></div>`);
            continue;
        }
        // "Race: Human | Origin: Outworlder": one row per labelled part; an unlabelled part joins the one before
        const parts = [];
        for (const f of fields) {
            if (f.label || !parts.length) parts.push({ label: f.label, values: [f.value] });
            else parts[parts.length - 1].values.push(f.value);
        }
        parts.forEach((p, i) => {
            const val = p.values.length > 1 ? p.values.map(x => escapeHtml(x)).join(' <span style="opacity:.5">|</span> ') : hudCardValue(p.label, p.values[0]);
            rows.push(row(i === 0 ? c : '', label(p.label || ''), val));
        });
    }
    if (rows.length) html += `<div class="rh-grid">${rows.join('')}</div>`;
    if (mods.length) html += `<div class="rh-mods">${mods.join('')}</div>`;
    // inline blocks (Godmother, School Database, a D&D sheet): each its own panel
    const blocks = new Map();
    for (const l of lines) if (l.block) { if (!blocks.has(l.block)) blocks.set(l.block, []); blocks.get(l.block).push(l); }
    for (const [title, ls] of blocks) {
        const body = ls.filter(l => l.text.trim() !== `[${title}]`).map(l => {
            const fm = l.text.trim().match(/^([^:]{1,40}?):\s*(.*)$/);
            return fm && !/\d$/.test(fm[1]) ? `<span class="r"><span class="rh-k">${escapeHtml(fm[1])}</span>${hudCardValue(fm[1], fm[2])}</span>` : `<span class="r">${escapeHtml(l.text.trim())}</span>`;
        });
        html += `<span class="rh-blk"><span class="h">${escapeHtml(title)}</span>${body.join('')}</span>`;
    }
    if (rows.some(r => r.startsWith('<div class="rh-row rh-c"')) || mods.some(m => m.includes(' rh-c'))) html += '<span class="rh-legend"><span class="dot">•</span> keeps its lorebook entry loading</span>';
    html += `<details class="rh-raw"${cfg.hudRawOpen ? ' open' : ''}><summary>Show the HUD as text</summary><pre>${escapeHtml(rawHud)}</pre></details>`;
    html += '</div>';
    return `<style>${HUD_CARD_CSS}</style>${html}`;
}

/** Replaces the plain-text HUD in a displayed reply with the card. Leaves anything it cannot read alone. */
function renderHudCard(text, cfg = chatDisplayCfg()) {
    if (!cfg.hudCard || !text || !HUD_HEAD_RE.test(text)) return text;
    const f = findHud(text);
    if (!f || f.fromHtml || !f.sepFound) return text;             // still streaming, or a HUD written as HTML
    const hud = parseHud(text);
    if (!hud) return text;
    let end = text.indexOf('\n', f.bodyEnd);
    end = end === -1 ? text.length : end + 1;                   // through the *** line
    const raw = text.slice(f.headStart, end).replace(/\s+$/, '');
    const card = i18nHtml(hudCardHtml(hud, raw, cfg), HUD_CARD_I18N);
    if (!card) return text;
    const before = text.slice(0, f.headStart).replace(/\s+$/, '');
    const after = text.slice(end).replace(/^\s+/, '');
    return `${before ? before + '\n\n' : ''}${card}\n\n${after}`;
}

// ── Dialogue: [D:Speaker:mood]"…"[/D] ──

